def check_following(response):
    sections = response.split("\n\n")
    if len(sections) != 3:
        return False

    for section in sections:
        lines = section.strip().split("\n")
        if len(lines) < 2:
            return False
        title, content = lines[0], "\n".join(lines[1:])
        if not title.strip() or title.strip() == title.strip().lower():
            return False
        sentences = re.split(r'(?<!\w\.\w.)(?<![A-Z][a-z]\.)(?<=\.|\?)\s', content)
        if len([s for s in sentences if s.strip()]) < 2:
            return False

    return True

