def check_following(response):
    paragraphs = response.strip().split('\n\n')
    if len(paragraphs) != 3:
        return False

    keywords = set()
    for paragraph in paragraphs:
        first_word = re.match(r'^\w+', paragraph)
        if not first_word:
            return False
        keyword = first_word.group(0).lower()
        if keyword in keywords:
            return False
        keywords.add(keyword)

    return True

